fn solve(m: i8, d: i8) -> i8 {
    // Number of days in each month for a non‐leap year.
    // Indexed by month-1: January is index 0, December is index 11.
    const DAYS_IN_MONTH: [i8; 12] = [
        31, // January
        28, // February
        31, // March
        30, // April
        31, // May
        30, // June
        31, // July
        31, // August
        30, // September
        31, // October
        30, // November
        31, // December
    ];

    // Look up the number of days in month `m`.
    let days = DAYS_IN_MONTH[(m - 1) as usize];

    // Compute how many "slots" are used on the calendar before the month ends.
    // We have (d-1) leading empty slots, plus `days` actual days.
    let total_slots = (d - 1) + days;

    // The number of weeks spanned is the ceiling of total_slots/7.
    // Ceil(x/7) = (x + 7 - 1) / 7 = (total_slots + 6) / 7
    (total_slots + 6) / 7
}

fn main() {
    // Examples
    assert_eq!(solve(1, 1), 5); // January starting on Monday: 31 days → spans 5 weeks
    assert_eq!(solve(2, 1), 4); // February starting on Monday: 28 days → spans 4 weeks
    assert_eq!(solve(3, 3), 5); // March starting on Wednesday: spans 5 weeks
    assert_eq!(solve(4, 7), 5); // April starting on Sunday: spans 5 weeks
    assert_eq!(solve(5, 6), 6); // May starting on Saturday: spans 6 weeks
    println!("All tests passed!");
}